  pi.bash({ cmd: 'git status --porcelain' }),
  pi.bash({ cmd: 'git diff HEAD --stat' }),
  pi.bash({ cmd: 'git log --oneline -8' }),
]);
return { status: status.output, diff: diff.output, log: log.output };

